#include <algorithm>
#include <cstddef>
#include <iostream>
#include <vector>

void moveZeroes(std::vector<int>& nums) {
    int write = 0;
    for (int num : nums) {
        if (num != 0) {
            nums[write] = num;
            write++;
        }
    }
    std::fill(nums.begin() + write, nums.end(), 0);
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    moveZeroes(nums);
    for (std::size_t i = 0; i < nums.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << nums[i];
    }
    std::cout << "\n";
    return 0;
}

