	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	moveZeroes(nums)
	parts := make([]string, n)
	for i, num := range nums {
		parts[i] = strconv.Itoa(num)
	}
